#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <string.h>
static double concentration(uint64_t *hist, size_t n) { uint64_t best=0; for(int i=0;i<252;i++){uint64_t count=0;for(int j=0;j<5;j++)count+=hist[i+j];if(count>best)best=count;}return (double)best/n;}
int main(int argc,char **argv) {
 if(argc!=3)return 2; int width=atoi(argv[1]),height=atoi(argv[2]); size_t ysize=(size_t)width*height,csize=ysize/4,size=ysize+2*csize;
 uint8_t *buf=malloc(size),*prev=malloc(ysize); if(!buf||!prev)return 3; size_t index=0;
 puts("frame,meanY,stdY,minY,maxY,darkFraction,brightFraction,modal5Y,modal5U,modal5V,meanAbsDiffPreviousY");
 for(;;){size_t have=0;while(have<size){size_t got=fread(buf+have,1,size-have,stdin);if(!got)break;have+=got;}if(!have)break;if(have!=size){fprintf(stderr,"partial frame: %zu/%zu",have,size);return 4;}
 uint64_t hist[3][256]={{0}},sum=0,sumsq=0,dark=0,bright=0,diff=0;int low=255,high=0;
 for(size_t i=0;i<ysize;i++){unsigned v=buf[i];hist[0][v]++;sum+=v;sumsq+=(uint64_t)v*v;if(v<low)low=v;if(v>high)high=v;if(v<=20)dark++;if(v>=232)bright++;if(index)diff+=(unsigned)abs((int)v-(int)prev[i]);}
 for(size_t i=0;i<csize;i++){hist[1][buf[ysize+i]]++;hist[2][buf[ysize+csize+i]]++;}
 double mean=(double)sum/ysize,variance=(double)sumsq/ysize-mean*mean;
 printf("%zu,%.8f,%.8f,%d,%d,%.10f,%.10f,%.10f,%.10f,%.10f,%.8f\n",index,mean,sqrt(variance>0?variance:0),low,high,(double)dark/ysize,(double)bright/ysize,concentration(hist[0],ysize),concentration(hist[1],csize),concentration(hist[2],csize),index?(double)diff/ysize:0);
 memcpy(prev,buf,ysize);index++;
 }
 fprintf(stderr,"decoded_complete_frames=%zu\n",index);free(buf);free(prev);return 0;
}
